const bar = morse.el("div", { id: "rb-progress", role: "progressbar", "aria-label": "Reading progress", "aria-valuemin": "0", "aria-valuemax": "100" });
document.body.appendChild(bar);
const update = () => {
  const h = document.documentElement.scrollHeight - window.innerHeight;
  const p = h > 0 ? Math.min(100, Math.max(0, (window.scrollY / h) * 100)) : 0;
  bar.style.width = p + "%";
  bar.setAttribute("aria-valuenow", Math.round(p));
};
morse.on(window, "scroll", update);
morse.on(window, "resize", update);
update();

