results.js:
morse.watch(".mn > h1", h => {
  if (h.querySelector(".mx-export")) return;
  const btn = morse.el("button", {
    class: "mx-export",
    type: "button",
    "aria-label": "Export orders to CSV",
    text: "Export CSV",
    on: { click: () => {
      const t = document.querySelector(".tbl table");
      if (!t) return;
      const q = v => '"' + v.replace(/"/g, '""').trim() + '"';
      const rows = [...t.querySelectorAll("tr")].map(tr =>
        [...tr.children].map(c => q(c.textContent)).join(","));
      const blob = new Blob([rows.join("\n")], { type: "text/csv" });
      const url = URL.createObjectURL(blob);
      const a = morse.el("a", { href: url, download: "orders.csv" });
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      morse.toast("Exported " + (rows.length - 1) + " orders");
    } }
  });
  h.appendChild(btn);
});

