morse.watch('header[role="banner"] .h7r', box => {
  if (box.querySelector('.copy-md-btn')) return;
  const btn = morse.el('button', {
    class: 'copy-md-btn',
    type: 'button',
    'aria-label': 'Copy conversation as markdown',
    text: 'Copy markdown',
    on: {
      click: async () => {
        const msgs = morse.$$('section[aria-label="Conversation"] .msg');
        if (!msgs.length) { morse.toast('No conversation to copy'); return; }
        const md = msgs.map(m => {
          const who = m.dataset.role === 'user' ? 'User' : 'Assistant';
          return '**' + who + ':**\n\n' + m.innerText.trim();
        }).join('\n\n---\n\n');
        try {
          await navigator.clipboard.writeText(md);
          btn.textContent = 'Copied';
          setTimeout(() => { btn.textContent = 'Copy markdown'; }, 1500);
          morse.toast('Conversation copied as markdown');
        } catch (e) {
          morse.toast('Could not copy');
        }
      }
    }
  });
  box.insertBefore(btn, box.firstChild);
});

