morse.watch("button.del", btn => {
  btn.addEventListener("click", e => {
    if (btn.dataset.ok) { delete btn.dataset.ok; return; }
    e.stopImmediatePropagation();
    e.preventDefault();
    if (btn.nextElementSibling && btn.nextElementSibling.classList.contains("del-confirm")) return;
    const close = () => { box.remove(); btn.style.display = ""; };
    const no = morse.el("button", { type: "button", text: "Cancel", on: { click: close } });
    const yes = morse.el("button", { type: "button", class: "yes", text: "Delete", on: { click: () => { close(); btn.dataset.ok = "1"; btn.click(); } } });
    const box = morse.el("span", { class: "del-confirm", role: "group", "aria-label": "Confirm delete" }, "Delete?", yes, no);
    btn.style.display = "none";
    btn.after(box);
    no.focus();
  }, true);
});

