morse.watch('#__next > div:nth-of-type(2) > main > div:nth-of-type(1)', bar => {
  if (bar.querySelector('[data-sort-price]')) return;
  const grid = () => bar.parentElement.querySelector(':scope > div:nth-of-type(2)');
  const price = c => {
    const m = c.textContent.match(/\$\s*([\d,]+(?:\.\d+)?)/);
    return m ? parseFloat(m[1].replace(/,/g, '')) : Infinity;
  };
  const btn = morse.el('button', {
    'data-sort-price': '',
    type: 'button',
    text: 'Sort: Price low to high',
    style: 'margin-left:auto;height:32px;padding:0 12px;font:600 14px "Helvetica Neue",Arial,sans-serif;color:#1c1917;background:#f5f5f4;border:1px solid #d6d3d1;border-radius:8px;cursor:pointer',
    on: {
      click: () => {
        const g = grid();
        if (!g) return;
        [...g.children]
          .map((c, i) => [c, i])
          .sort((a, b) => price(a[0]) - price(b[0]) || a[1] - b[1])
          .forEach(([c]) => g.appendChild(c));
        btn.textContent = 'Sorted: lowest first ✓';
      }
    }
  });
  bar.appendChild(btn);
});

