morse.watch('[data-testid="player-controls"] .btns', box => {
  const opts = [0, 15, 30, 60];
  let end = morse.store.get('sleepEnd') || 0;
  if (end < Date.now()) end = 0;
  const b = morse.el('button', {'data-sleep': '1', 'aria-label': 'Sleep timer', title: 'Sleep timer', text: '☾'});
  const render = () => {
    const left = end ? Math.ceil((end - Date.now()) / 60000) : 0;
    b.textContent = left ? '☾ ' + left + 'm' : '☾';
    b.title = left ? 'Sleep timer: pauses in ' + left + ' min (click to change)' : 'Sleep timer: off';
  };
  b.addEventListener('click', () => {
    const left = end ? Math.ceil((end - Date.now()) / 60000) : 0;
    const cur = left > 30 ? 60 : left > 15 ? 30 : left > 0 ? 15 : 0;
    const next = opts[(opts.indexOf(cur) + 1) % opts.length];
    end = next ? Date.now() + next * 60000 : 0;
    morse.store.set('sleepEnd', end);
    morse.toast(next ? 'Sleep timer: ' + next + ' min' : 'Sleep timer off');
    render();
  });
  box.appendChild(b);
  render();
  morse.every(1000, () => {
    if (end && Date.now() >= end) {
      end = 0;
      morse.store.set('sleepEnd', 0);
      const p = document.querySelector('[data-testid="play-pause"][aria-label="Pause"]');
      if (p) p.click();
      morse.toast('Sleep timer: paused');
    }
    render();
  });
});

